import { render, screen, fireEvent, waitFor } from '@testing-library/react'
import { test, expect, vi } from 'vitest'

test('React 19 form action', async () => {
  const fn = vi.fn(async (formData: FormData) => {
    console.log('Action called with name:', formData.get('name'))
  })

  function TestForm() {
    return (
      <form action={fn}>
        <input name="name" defaultValue="Alice" />
        <button type="submit">Submit</button>
      </form>
    )
  }

  render(<TestForm />)
  fireEvent.click(screen.getByRole('button'))
  await waitFor(() => {
    expect(fn).toHaveBeenCalled()
  })
})

import { render, screen, fireEvent } from '@testing-library/react'
import { test, expect } from 'vitest'

test('form action throws', async () => {
  async function action(formData: FormData) {
    'use server'
    const name = formData.get('name')
    if (!name) {
      throw new Error('Name is required')
    }
  }

  function Form() {
    return (
      <form action={action}>
        <input name="name" />
        <button type="submit">Submit</button>
      </form>
    )
  }

  render(<Form />)
  try {
    fireEvent.click(screen.getByRole('button'))
  } catch (e) {
    console.log('Caught synchronous error:', e)
  }
})

import { render } from '@testing-library/react'
import { test } from 'vitest'

test('form action attribute', () => {
  async function action(formData: FormData) {
    'use server'
  }
  function Form() {
    return (
      <form action={action}>
        <input name="name" />
      </form>
    )
  }
  const { container } = render(<Form />)
  const form = container.querySelector('form')
  console.log('form.action:', form?.getAttribute('action'), form?.action)
})

