export async function saveContactMessage(formData: FormData) {
  'use server'

  const name = formData.get('name') as string
  const email = formData.get('email') as string
  const message = formData.get('message') as string

  if (!name || !email || !message || !name.trim() || !email.trim() || !message.trim()) {
    throw new Error('All fields are required')
  }

  console.log('Saving contact message:', { name, email, message })
  return { success: true }
}

export default function ContactForm() {
  async function submitContact(formData: FormData) {
    'use server'
    return saveContactMessage(formData)
  }

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={submitContact}>
        <input name="name" placeholder="Name" required />
        <input name="email" type="email" placeholder="Email" required />
        <textarea name="message" placeholder="Message" required />
        <button type="submit">Submit</button>
      </form>
    </div>
  )
}

